CREATE OR REPLACE FUNCTION public.sgp_aluminio_pendiente_revertir_avance_v1(p_token text, p_id uuid, p_movimiento uuid, p_clave uuid, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 u text;
 p public.sgp_aluminio_pendientes%rowtype;
 a public.sgp_aluminio_pendiente_movimientos%rowtype;
 e public.sgp_aluminio_pendiente_movimientos%rowtype;
 nuevo uuid;
BEGIN
 u := public.sgp_pdt_validar_rol_real(p_token, ARRAY['ADMINISTRADOR','COORDINADOR','LIDER MECANIZADO','LIDER']);
 IF p_id IS NULL OR p_movimiento IS NULL OR p_clave IS NULL OR nullif(btrim(p_motivo),'') IS NULL
 THEN RAISE EXCEPTION 'Parametros invalidos'; END IF;
 SELECT * INTO p FROM public.sgp_aluminio_pendientes WHERE id_pendiente=p_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Pendiente inexistente'; END IF;
 SELECT * INTO e FROM public.sgp_aluminio_pendiente_movimientos WHERE idempotency_key=p_clave;
 IF FOUND THEN
  IF e.tipo <> 'REVERSO' OR e.id_pendiente <> p_id OR e.id_movimiento_revertido <> p_movimiento OR e.observacion IS DISTINCT FROM p_motivo
  THEN RAISE EXCEPTION 'Clave reutilizada'; END IF;
  RETURN jsonb_build_object('ok',true,'duplicado',true,'id_movimiento',e.id_movimiento);
 END IF;
 IF p.estado <> 'PENDIENTE' OR p.estado_repo = 'PICKING' OR p.fecha_cierre IS NOT NULL
 THEN RAISE EXCEPTION 'Pendiente no apto'; END IF;
 SELECT * INTO a FROM public.sgp_aluminio_pendiente_movimientos
 WHERE id_movimiento=p_movimiento AND id_pendiente=p_id AND tipo='AVANCE' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Avance inexistente'; END IF;
 IF EXISTS (SELECT 1 FROM public.sgp_aluminio_pendiente_movimientos WHERE id_movimiento_revertido=p_movimiento)
 THEN RAISE EXCEPTION 'Avance ya revertido'; END IF;
 IF p.contrato_pdt<>'V2' OR p.validacion_estado<>'VALIDADO' THEN RAISE EXCEPTION 'PDT no V2 validado'; END IF;
 IF (SELECT coalesce(sum(CASE WHEN tipo='AVANCE' THEN cantidad ELSE -cantidad END),0)
 FROM public.sgp_aluminio_pendiente_movimientos WHERE id_detalle=a.id_detalle)-a.cantidad
 <public.sgp_pdt_comprometido(a.id_detalle) THEN RAISE EXCEPTION 'Reverso afecta entrega Picking'; END IF;
 INSERT INTO public.sgp_aluminio_pendiente_movimientos
 (id_pendiente,id_detalle,tipo,cantidad,id_movimiento_revertido,idempotency_key,usuario,turno,fecha_operativa,observacion)
 VALUES (p_id,a.id_detalle,'REVERSO',a.cantidad,p_movimiento,p_clave,u,a.turno,a.fecha_operativa,p_motivo)
 RETURNING id_movimiento INTO nuevo;
 INSERT INTO public.sgp_aluminio_pendientes_historial (id_pendiente,usuario,observacion,tipo_evento,estado_anterior,estado_nuevo,datos_nuevos)
 VALUES (p_id,u,p_motivo,'REVERSO_AVANCE_PDT',p.estado_repo,CASE WHEN p.estado_repo='PROCESADO' THEN 'MECANIZADO' ELSE p.estado_repo END,jsonb_build_object('original',p_movimiento,'reverso',nuevo,'cantidad',a.cantidad));
 IF p.estado_repo='PROCESADO' THEN
  UPDATE public.sgp_aluminio_pendientes SET estado_repo='MECANIZADO',usuario_estado=u,fecha_estado=now() WHERE id_pendiente=p_id;
 END IF;
 RETURN jsonb_build_object('ok',true,'duplicado',false,'id_movimiento',nuevo);
END $function$

CREATE OR REPLACE FUNCTION public.sgp_aluminio_pendiente_nc_vincular_v1(p_token text, p_id uuid, p_ncs text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 u text; p public.sgp_aluminio_pendientes%rowtype;
 snap jsonb; n text; canonical text; matches integer; inserted integer; added text[]:=ARRAY[]::text[]; ncs text[]:=ARRAY[]::text[];
BEGIN
 u:=public.sgp_validar_sesion_rol(p_token,ARRAY['ADMINISTRADOR','COORDINADOR','PATINADOR']);
 IF p_id IS NULL OR p_ncs IS NULL OR cardinality(p_ncs) NOT BETWEEN 1 AND 30
 THEN RAISE EXCEPTION 'Listado NC invalido'; END IF;
 SELECT * INTO p FROM public.sgp_aluminio_pendientes WHERE id_pendiente=p_id FOR UPDATE;
 IF NOT FOUND OR p.estado <> 'PENDIENTE' OR p.fecha_cierre IS NOT NULL OR p.estado_repo='PICKING' THEN RAISE EXCEPTION 'Pendiente no activo'; END IF;
 FOREACH n IN ARRAY p_ncs LOOP
  n:=btrim(n);
  IF n IS NULL OR length(n) NOT BETWEEN 1 AND 120 OR n ~ '[[:cntrl:]]' THEN RAISE EXCEPTION 'Consecutivo NC invalido'; END IF;
  SELECT count(DISTINCT nc.consecutivo),min(nc.consecutivo) INTO matches,canonical
 FROM public.sgp_nc_aluminio nc WHERE nc.consecutivo=n OR nc.cod_nc=n;
 IF matches>1 THEN RAISE EXCEPTION 'NC ambigua: %',n; END IF;
 IF matches=1 THEN n:=canonical; END IF;
  IF NOT (n=ANY(ncs)) THEN ncs:=array_append(ncs,n); END IF;
 END LOOP;
 FOREACH n IN ARRAY ncs LOOP
  SELECT to_jsonb(nc) INTO snap FROM public.sgp_nc_aluminio nc WHERE nc.consecutivo=n
  ORDER BY nc.fecha_actualizacion DESC NULLS LAST,nc.creacion DESC NULLS LAST LIMIT 1;
  IF snap IS NOT NULL THEN
   INSERT INTO public.sgp_aluminio_pendiente_ncs(id_pendiente,consecutivo,enlazado_por,snapshot)
   VALUES(p_id,n,u,snap) ON CONFLICT DO NOTHING;
   GET DIAGNOSTICS inserted=ROW_COUNT;
  ELSE
   SELECT CASE WHEN EXISTS (SELECT 1 FROM public.sgp_aluminio_pendientes_historial h CROSS JOIN LATERAL jsonb_array_elements_text(CASE WHEN jsonb_typeof(h.datos_nuevos->'ncs')='array' THEN h.datos_nuevos->'ncs' ELSE '[]'::jsonb END) x(ref) WHERE h.id_pendiente=p_id AND h.tipo_evento IN ('REGISTRO_MULTIORIGEN_V4','VINCULACION_NC_PDT') AND x.ref=n) OR n=ANY(regexp_split_to_array(coalesce(p.nc,''),'[,;]')) THEN 0 ELSE 1 END INTO inserted;
  END IF;
  IF inserted=1 THEN added:=array_append(added,n); END IF;
 END LOOP;
 IF cardinality(added)>0 THEN
 INSERT INTO public.sgp_aluminio_pendientes_historial(id_pendiente,estado_nuevo,usuario,tipo_evento,datos_nuevos)
 VALUES(p_id,p.estado,u,'VINCULACION_NC_PDT',jsonb_build_object('ncs',added,'referencias_solicitadas',p_ncs));
 END IF;
 RETURN jsonb_build_object('ok',true,'ncs',ncs,'agregadas',added,'duplicado',cardinality(added)=0);
END $function$

CREATE OR REPLACE FUNCTION public.sgp_picking_validar_jornada_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_now timestamptz := statement_timestamp();
  v_local timestamp := v_now AT TIME ZONE 'America/Bogota';
  v_date date := v_local::date;
  v_hour time := v_local::time;
  v_prev date := v_date - 1;
  v_prev_sunday boolean := extract(isodow from v_prev) = 7;
  v_expected_date date;
  v_expected_turn text;
  v_start timestamptz;
  v_start_hour integer;
BEGIN
  IF v_hour >= time '07:00' THEN
    v_expected_date := v_date;
    IF extract(isodow from v_date) = 7 THEN
      v_expected_turn := CASE WHEN v_hour < time '18:00' THEN 'TURNO 1' ELSE 'TURNO 2' END;
    ELSE
      v_expected_turn := CASE WHEN v_hour < time '19:00' THEN 'TURNO 1' ELSE 'TURNO 2' END;
    END IF;
  ELSIF v_prev_sunday AND v_hour >= time '05:00' THEN
    v_expected_date := NULL; -- No active shift Monday 05:00-07:00.
  ELSE
    v_expected_date := v_prev;
    v_expected_turn := 'TURNO 2';
  END IF;

  -- Legacy 6-argument RPC omits both fields. Fill both from the actual active shift.
  IF NEW.fecha_operativa IS NULL AND NEW.turno_entrega IS NULL THEN
    IF v_expected_date IS NULL THEN
      RAISE EXCEPTION 'PICKING_SIN_TURNO_ACTIVO';
    END IF;
    NEW.fecha_operativa := v_expected_date;
    NEW.turno_entrega := v_expected_turn;
  ELSIF NEW.fecha_operativa IS NULL OR NEW.turno_entrega IS NULL THEN
    RAISE EXCEPTION 'PICKING_FECHA_TURNO_REQUERIDOS';
  END IF;

  NEW.turno_entrega := upper(btrim(NEW.turno_entrega));
  IF NEW.turno_entrega NOT IN ('TURNO 1','TURNO 2') THEN
    RAISE EXCEPTION 'PICKING_TURNO_INVALIDO';
  END IF;
  v_start_hour := CASE
    WHEN NEW.turno_entrega = 'TURNO 1' THEN 7
    WHEN extract(isodow from NEW.fecha_operativa) = 7 THEN 18
    ELSE 19
  END;
  v_start := (NEW.fecha_operativa::timestamp + make_interval(hours => v_start_hour))
    AT TIME ZONE 'America/Bogota';
  IF v_start > v_now THEN
    RAISE EXCEPTION 'PICKING_TURNO_FUTURO';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION sgp_pdt_multiorigen.original_sgp_aluminio_pendiente_validar_detalles_v1(p_token text, p_id uuid, p_detalles jsonb, p_reserva text DEFAULT NULL::text, p_observacion text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_usuario text; v_p public.sgp_aluminio_pendientes%rowtype;
 v_row jsonb; v_fab text; v_acab text; v_long numeric; v_cant integer;
 v_total bigint:=0; v_count integer:=0; v_first jsonb; v_source integer; v_detalle uuid; v_a public.sgp_aluminio%rowtype;
 v_key text; v_keys text[]:=array[]::text[]; v_out jsonb; v_correction boolean; v_res text; v_acab_res text;
BEGIN
 v_usuario:=public.sgp_validar_sesion_rol(p_token,ARRAY['ADMINISTRADOR','COORDINADOR','LIDER LINEA','SUPERVISOR DE PICKING','RECEPCION']);
 SELECT * INTO v_p FROM public.sgp_aluminio_pendientes WHERE id_pendiente=p_id FOR UPDATE;
 IF NOT FOUND OR v_p.estado<>'PENDIENTE' OR v_p.fecha_cierre IS NOT NULL OR coalesce(v_p.estado_repo,'PENDIENTE')='PICKING' OR coalesce(v_p.validacion_estado,'POR_VALIDAR')='VALIDADO'
 THEN RAISE EXCEPTION 'Pendiente no activo o ya validado'; END IF;
 IF p_detalles IS NULL OR jsonb_typeof(p_detalles)<>'array' OR jsonb_array_length(p_detalles) NOT BETWEEN 1 AND 100
 THEN RAISE EXCEPTION 'Se requiere entre 1 y 100 fabricaciones'; END IF;
 IF EXISTS (SELECT 1 FROM public.sgp_aluminio_pendiente_movimientos WHERE id_pendiente=p_id)
 THEN RAISE EXCEPTION 'No se puede revalidar un pendiente con movimientos'; END IF;
 FOR v_row IN SELECT value FROM jsonb_array_elements(p_detalles)
 LOOP
  v_count:=v_count+1;
  v_fab:=nullif(btrim(v_row->>'fabricacion'),'');
  v_acab:=nullif(btrim(v_row->>'acabado'),'');
  IF v_row->>'longitud' !~ '^[0-9]+([.][0-9]+)?$'
    OR v_row->>'cantidad' !~ '^[0-9]+$'
  THEN RAISE EXCEPTION 'Longitud y cantidad deben ser numéricas'; END IF;
  v_long:=(v_row->>'longitud')::numeric;
  IF length(v_row->>'cantidad')>10 OR (v_row->>'cantidad')::numeric>2147483647 THEN RAISE EXCEPTION 'Cantidad fuera de rango'; END IF;
  v_cant:=(v_row->>'cantidad')::integer;
  IF v_fab IS NULL OR v_acab IS NULL OR v_long<=0 OR v_cant<=0
  THEN RAISE EXCEPTION 'Fabricación, acabado, longitud y cantidad obligatorios'; END IF;
  v_key:=v_row->>'id_pieza';
  IF nullif(v_key,'') IS NULL THEN RAISE EXCEPTION 'Referencia fuente requerida'; END IF;
  IF v_key=ANY(v_keys) THEN RAISE EXCEPTION 'Fabricación repetida'; END IF;
  v_keys:=array_append(v_keys,v_key);
  IF v_count=1 THEN v_first:=v_row; END IF;
  v_total:=v_total+v_cant;
  IF v_total>2147483647 THEN RAISE EXCEPTION 'Cantidad fuera de rango'; END IF;
 PERFORM public.sgp_pdt_exigir_panel_v3(p_id);
  IF nullif(btrim(v_p.key_produccion),'') IS NULL THEN RAISE EXCEPTION 'Identidad producción no resuelta'; END IF;
  SELECT count(*) INTO v_source FROM public.sgp_aluminio a
   JOIN public.sgp_producciones prod ON prod.key_produccion=a.key_produccion
   WHERE a.id_pieza=v_key AND a.activo='SI' AND a.tipo_pieza='PANEL'
     AND a.key_produccion=v_p.key_produccion AND prod.id_linea='PANELES_2' AND btrim(a.produccion)=btrim(v_p.produccion)
     AND (nullif(btrim(coalesce(v_p.acabado_pendiente,'')),'') IS NULL OR upper(btrim(a.acabado))=upper(btrim(v_p.acabado_pendiente)))
     AND EXISTS(SELECT 1 FROM public.sgp_produccion_reservas_v r WHERE r.key_produccion=v_p.key_produccion AND r.reserva=coalesce(nullif(btrim(p_reserva),''),v_p.reserva) AND (r.acabado_reserva IS NULL OR upper(btrim(r.acabado_reserva))=upper(btrim(a.acabado))))
     AND upper(btrim(a.sistema))=upper(btrim(prod.sistema))
     AND btrim(a.codigo_sap)=btrim(v_p.perfil)
     AND lower(btrim(a.fabricacion))=lower(v_fab) AND a.longitud=v_long
     AND upper(btrim(a.acabado))=upper(v_acab);
  IF v_source<>1 THEN RAISE EXCEPTION 'Fuente PANEL inexistente o ambigua'; END IF;
 END LOOP;
 v_correction := v_total IS DISTINCT FROM v_p.cantidad;
 IF v_correction AND nullif(btrim(coalesce(p_observacion,'')),'') IS NULL
 THEN RAISE EXCEPTION 'Corrección de cantidad requiere observación'; END IF;
 -- Dedicated validation for this new RPC. Legacy validator is not modified.
 v_res:=coalesce(nullif(btrim(coalesce(p_reserva,'')),''),v_p.reserva);
 v_acab_res:=coalesce(nullif(btrim(coalesce(v_p.acabado_pendiente,'')),''),nullif(btrim(v_first->>'acabado'),''));
 IF v_res IS NULL OR v_acab_res IS NULL THEN RAISE EXCEPTION 'Reserva y acabado obligatorios'; END IF;
 IF nullif(btrim(coalesce(v_p.key_produccion,'')),'') IS NOT NULL
 AND NOT EXISTS (SELECT 1 FROM public.sgp_produccion_reservas_v r
  WHERE r.key_produccion=v_p.key_produccion AND r.reserva=v_res
    AND (r.acabado_reserva IS NULL OR upper(btrim(r.acabado_reserva))=upper(v_acab_res)))
 THEN RAISE EXCEPTION 'Reserva/acabado no pertenece a producción'; END IF;
 IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_detalles) d
  WHERE upper(btrim(d->>'acabado'))<>upper(v_acab_res))
 THEN RAISE EXCEPTION 'Acabado distinto al de la reserva'; END IF;
 INSERT INTO public.sgp_aluminio_pendientes_historial
 (id_pendiente,estado_nuevo,usuario,observacion,tipo_evento,datos_anteriores,datos_nuevos)
 VALUES(p_id,coalesce(v_p.estado_repo,'PENDIENTE'),v_usuario,p_observacion,'VALIDACION_PDT',
  jsonb_build_object('fabricacion',v_p.fabricacion,'longitud',v_p.longitud,
   'reserva',v_p.reserva,'acabado',v_p.acabado_pendiente,'validacion_estado',v_p.validacion_estado),
  jsonb_build_object('fabricacion',v_first->>'fabricacion','reserva',v_res,
   'acabado',v_acab_res,'validacion_estado','VALIDADO'));
 FOR v_row IN SELECT value FROM jsonb_array_elements(p_detalles)
 LOOP
  INSERT INTO public.sgp_aluminio_pendiente_detalles
   (id_pendiente,id_pieza,fabricacion,longitud,acabado,cantidad_validada,creado_por)
  VALUES (p_id,v_row->>'id_pieza',btrim(v_row->>'fabricacion'),(v_row->>'longitud')::numeric,
          btrim(v_row->>'acabado'),(v_row->>'cantidad')::integer,v_usuario) RETURNING id_detalle INTO v_detalle;
  SELECT * INTO STRICT v_a FROM public.sgp_aluminio WHERE id_pieza=v_row->>'id_pieza';
  INSERT INTO public.sgp_pdt_fuentes(id_detalle,id_pieza,id_carga,fila_origen,snapshot)
  VALUES(v_detalle,v_a.id_pieza,v_a.id_carga,v_a.fila_origen,to_jsonb(v_a));
 END LOOP;
 UPDATE public.sgp_aluminio_pendientes SET contrato_pdt='V2',
  fabricacion=btrim(v_first->>'fabricacion'),longitud=(v_first->>'longitud')::numeric,
  reserva=v_res,acabado_pendiente=v_acab_res,validacion_estado='VALIDADO',
  validado_por=v_usuario,fecha_validacion=now(),
  observacion_validacion=nullif(btrim(coalesce(p_observacion,'')),'')
 WHERE id_pendiente=p_id;
 INSERT INTO public.sgp_aluminio_pendientes_historial
 (id_pendiente,estado_nuevo,usuario,observacion,tipo_evento,datos_anteriores,datos_nuevos)
 VALUES(p_id,coalesce(v_p.estado_repo,'PENDIENTE'),v_usuario,p_observacion,'VALIDACION_DETALLES_PDT',
  jsonb_build_object('cantidad_reportada',v_p.cantidad,'fabricacion_reportada',v_p.fabricacion),
  jsonb_build_object('cantidad_validada',v_total,'correccion',v_correction,'detalles',p_detalles));
 RETURN jsonb_build_object('ok',true,'cantidad_reportada',v_p.cantidad,'cantidad_validada',v_total,'detalles',v_count);
END $function$

CREATE OR REPLACE FUNCTION sgp_pdt_multiorigen.nuevo_sgp_aluminio_pendiente_validar_detalles_v1(p_token text, p_id uuid, p_detalles jsonb, p_reserva text DEFAULT NULL::text, p_observacion text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_usuario text; v_p public.sgp_aluminio_pendientes%rowtype;
 v_row jsonb; v_fab text; v_acab text; v_long numeric; v_cant integer;
 v_total bigint:=0; v_count integer:=0; v_first jsonb; v_source integer; v_detalle uuid; v_a public.sgp_aluminio%rowtype;
 v_key text; v_keys text[]:=array[]::text[]; v_out jsonb; v_correction boolean; v_res text; v_acab_res text;
BEGIN
 v_usuario:=public.sgp_validar_sesion_rol(p_token,ARRAY['ADMINISTRADOR','COORDINADOR','LIDER LINEA','SUPERVISOR DE PICKING','RECEPCION']);
 SELECT * INTO v_p FROM public.sgp_aluminio_pendientes WHERE id_pendiente=p_id FOR UPDATE;
 IF NOT FOUND OR v_p.estado<>'PENDIENTE' OR v_p.fecha_cierre IS NOT NULL OR coalesce(v_p.estado_repo,'PENDIENTE')='PICKING' OR coalesce(v_p.validacion_estado,'POR_VALIDAR')='VALIDADO'
 THEN RAISE EXCEPTION 'Pendiente no activo o ya validado'; END IF;
 IF p_detalles IS NULL OR jsonb_typeof(p_detalles)<>'array' OR jsonb_array_length(p_detalles) NOT BETWEEN 1 AND 100
 THEN RAISE EXCEPTION 'Se requiere entre 1 y 100 fabricaciones'; END IF;
 IF EXISTS (SELECT 1 FROM public.sgp_aluminio_pendiente_movimientos WHERE id_pendiente=p_id)
 THEN RAISE EXCEPTION 'No se puede revalidar un pendiente con movimientos'; END IF;
 FOR v_row IN SELECT value FROM jsonb_array_elements(p_detalles)
 LOOP
  v_count:=v_count+1;
  v_fab:=nullif(btrim(v_row->>'fabricacion'),'');
  v_acab:=nullif(btrim(v_row->>'acabado'),'');
  IF v_row->>'longitud' !~ '^[0-9]+([.][0-9]+)?$'
    OR v_row->>'cantidad' !~ '^[0-9]+$'
  THEN RAISE EXCEPTION 'Longitud y cantidad deben ser numéricas'; END IF;
  v_long:=(v_row->>'longitud')::numeric;
  IF length(v_row->>'cantidad')>10 OR (v_row->>'cantidad')::numeric>2147483647 THEN RAISE EXCEPTION 'Cantidad fuera de rango'; END IF;
  v_cant:=(v_row->>'cantidad')::integer;
  IF v_fab IS NULL OR v_acab IS NULL OR v_long<=0 OR v_cant<=0
  THEN RAISE EXCEPTION 'Fabricación, acabado, longitud y cantidad obligatorios'; END IF;
  v_key:=v_row->>'id_pieza';
  IF nullif(v_key,'') IS NULL THEN RAISE EXCEPTION 'Referencia fuente requerida'; END IF;
  IF v_key=ANY(v_keys) THEN RAISE EXCEPTION 'Fabricación repetida'; END IF;
  v_keys:=array_append(v_keys,v_key);
  IF v_count=1 THEN v_first:=v_row; END IF;
  v_total:=v_total+v_cant;
  IF v_total>2147483647 THEN RAISE EXCEPTION 'Cantidad fuera de rango'; END IF;
 PERFORM public.sgp_pdt_exigir_panel_v3(p_id);
  IF nullif(btrim(v_p.key_produccion),'') IS NULL THEN RAISE EXCEPTION 'Identidad producción no resuelta'; END IF;
  -- Direct, physical-source validation as in production. A legacy imported
  -- source key may point at FRAME, but its base ID and PANEL master must prove
  -- ONE matching PANEL target. No name-only match and no generic source helper.
  SELECT count(*) INTO v_source FROM public.sgp_aluminio a
  JOIN public.sgp_producciones origin ON origin.key_produccion=a.key_produccion
  JOIN public.sgp_producciones prod ON prod.id=origin.id AND nullif(btrim(origin.id),'') IS NOT NULL
  JOIN public.sgp_maestro_piezas m ON m.codigo_sap=a.codigo_sap
  WHERE a.id_pieza=v_key AND a.activo='SI' AND a.tipo_pieza='PANEL'
   AND m.activo='SI' AND m.tipo_pieza='PANEL' AND m.destino_productivo='PANEL'
   AND origin.id_linea IN ('PANELES_2','FRAMES_2') AND prod.id_linea='PANELES_2'
   AND prod.key_produccion=v_p.key_produccion
   AND btrim(a.produccion)=btrim(v_p.produccion) AND btrim(origin.produccion)=btrim(prod.produccion)
   AND upper(btrim(a.sistema))=upper(btrim(prod.sistema)) AND upper(btrim(origin.sistema))=upper(btrim(prod.sistema))
   AND btrim(a.codigo_sap)=btrim(v_p.perfil)
   AND lower(btrim(a.fabricacion))=lower(v_fab) AND a.longitud=v_long AND upper(btrim(a.acabado))=upper(v_acab)
   AND (nullif(btrim(v_p.acabado_pendiente),'') IS NULL OR upper(btrim(a.acabado))=upper(btrim(v_p.acabado_pendiente)))
   AND EXISTS(SELECT 1 FROM public.sgp_produccion_reservas_v r
    WHERE r.key_produccion=prod.key_produccion AND r.reserva=coalesce(nullif(btrim(p_reserva),''),v_p.reserva)
    AND (NOT coalesce(r.es_reserva_compartida,false) OR nullif(btrim(r.reserva_principal),'') IS NOT NULL)
    AND (r.acabado_reserva IS NULL OR upper(btrim(r.acabado_reserva))=upper(btrim(a.acabado))))
   AND (SELECT count(*) FROM public.sgp_producciones other WHERE other.id=origin.id AND other.id_linea='PANELES_2')=1;
  IF v_source<>1 THEN RAISE EXCEPTION 'Fuente PANEL inexistente o ambigua'; END IF;
 END LOOP;
 v_correction := v_total IS DISTINCT FROM v_p.cantidad;
 IF v_correction AND nullif(btrim(coalesce(p_observacion,'')),'') IS NULL
 THEN RAISE EXCEPTION 'Corrección de cantidad requiere observación'; END IF;
 -- Dedicated validation for this new RPC. Legacy validator is not modified.
 v_res:=coalesce(nullif(btrim(coalesce(p_reserva,'')),''),v_p.reserva);
 v_acab_res:=coalesce(nullif(btrim(coalesce(v_p.acabado_pendiente,'')),''),nullif(btrim(v_first->>'acabado'),''));
 IF v_res IS NULL OR v_acab_res IS NULL THEN RAISE EXCEPTION 'Reserva y acabado obligatorios'; END IF;
 IF nullif(btrim(coalesce(v_p.key_produccion,'')),'') IS NOT NULL
 AND NOT EXISTS (SELECT 1 FROM public.sgp_produccion_reservas_v r
  WHERE r.key_produccion=v_p.key_produccion AND r.reserva=v_res
    AND (r.acabado_reserva IS NULL OR upper(btrim(r.acabado_reserva))=upper(v_acab_res)))
 THEN RAISE EXCEPTION 'Reserva/acabado no pertenece a producción'; END IF;
 IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_detalles) d
  WHERE upper(btrim(d->>'acabado'))<>upper(v_acab_res))
 THEN RAISE EXCEPTION 'Acabado distinto al de la reserva'; END IF;
 INSERT INTO public.sgp_aluminio_pendientes_historial
 (id_pendiente,usuario,observacion,estado_anterior,estado_nuevo,tipo_evento,datos_anteriores,datos_nuevos)
 VALUES(p_id,v_usuario,p_observacion,v_p.estado_repo,v_p.estado_repo,'VALIDACION_PDT',
  jsonb_build_object('fabricacion',v_p.fabricacion,'longitud',v_p.longitud,
   'reserva',v_p.reserva,'acabado',v_p.acabado_pendiente,'validacion_estado',v_p.validacion_estado),
  jsonb_build_object('fabricacion',v_first->>'fabricacion','reserva',v_res,
   'acabado',v_acab_res,'validacion_estado','VALIDADO'));
 FOR v_row IN SELECT value FROM jsonb_array_elements(p_detalles)
 LOOP
  INSERT INTO public.sgp_aluminio_pendiente_detalles
   (id_pendiente,id_pieza,fabricacion,longitud,acabado,cantidad_validada,creado_por)
  VALUES (p_id,v_row->>'id_pieza',btrim(v_row->>'fabricacion'),(v_row->>'longitud')::numeric,
          btrim(v_row->>'acabado'),(v_row->>'cantidad')::integer,v_usuario) RETURNING id_detalle INTO v_detalle;
  SELECT * INTO STRICT v_a FROM public.sgp_aluminio WHERE id_pieza=v_row->>'id_pieza';
  INSERT INTO public.sgp_pdt_fuentes(id_detalle,id_pieza,id_carga,fila_origen,snapshot)
  VALUES(v_detalle,v_a.id_pieza,v_a.id_carga,v_a.fila_origen,to_jsonb(v_a));
 END LOOP;
 UPDATE public.sgp_aluminio_pendientes SET contrato_pdt='V2',
  fabricacion=btrim(v_first->>'fabricacion'),longitud=(v_first->>'longitud')::numeric,
  reserva=v_res,acabado_pendiente=v_acab_res,validacion_estado='VALIDADO',
  validado_por=v_usuario,fecha_validacion=now(),
  observacion_validacion=nullif(btrim(coalesce(p_observacion,'')),'')
 WHERE id_pendiente=p_id;
 INSERT INTO public.sgp_aluminio_pendientes_historial
 (id_pendiente,usuario,observacion,estado_anterior,estado_nuevo,tipo_evento,datos_anteriores,datos_nuevos)
 VALUES(p_id,v_usuario,p_observacion,v_p.estado_repo,v_p.estado_repo,'VALIDACION_DETALLES_PDT',
